[CmdletBinding()]
param([string]$PackagePath=$PSScriptRoot)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
if($env:COMPUTERNAME -ne 'WIN-I123AM83GR4'){throw 'Wrong clinic host'}
function Invoke-PetHotelDocker([string[]]$Arguments){$saved=$ErrorActionPreference;try{$ErrorActionPreference='Continue';$r=& docker @Arguments 2>&1|Out-String;$rc=$LASTEXITCODE}finally{$ErrorActionPreference=$saved};if($rc -ne 0){throw "Docker $($Arguments[0]) failed: $r"};return $r}
$m=Get-Content (Join-Path $PackagePath 'release.json') -Raw|ConvertFrom-Json
foreach($kind in @('api','web')){$c=@(ConvertFrom-Json (Invoke-PetHotelDocker -Arguments @('inspect',('clinic-crm-'+$kind))))[0];if($c.Image -ne $m.previous.$kind.id){throw 'Running baseline changed'};$log=Invoke-PetHotelDocker -Arguments @('build','--platform','linux/amd64','--network','none','--pull=false','--build-arg',('BASE_'+$kind.ToUpperInvariant()+'_IMAGE='+$m.previous.$kind.reference),'--build-arg',('RELEASE_REVISION='+$m.revision),'-f',(Join-Path $PackagePath ('Dockerfile.'+$kind)),'-t',$m.images.$kind.reference,$PackagePath);[IO.File]::WriteAllText((Join-Path $PackagePath ($kind+'-build.log')),$log);$i=@(ConvertFrom-Json (Invoke-PetHotelDocker -Arguments @('image','inspect',$m.images.$kind.reference)))[0];if($i.Architecture -ne 'amd64'){throw 'Wrong candidate architecture'};$m.images.$kind.id=$i.Id}
$source="const f=require('fs'),p=require('path'),c=require('crypto'),o={};function w(d){for(const e of f.readdirSync(d,{withFileTypes:true})){const n=p.join(d,e.name);if(e.isDirectory())w(n);else if(e.isFile())o[n]=c.createHash('sha256').update(f.readFileSync(n)).digest('hex');}}w('/app/apps/api/dist');console.log(JSON.stringify(o));"
$old=ConvertFrom-Json (Invoke-PetHotelDocker -Arguments @('run','--rm','--network','none','--entrypoint','node',$m.previous.api.id,'-e',$source));$new=ConvertFrom-Json (Invoke-PetHotelDocker -Arguments @('run','--rm','--network','none','--entrypoint','node',$m.images.api.id,'-e',$source))
$count=0;foreach($p in $old.PSObject.Properties){if($p.Name -match '/dist/(app\.module\.(js|js\.map|d\.ts)$|modules/(pet-hotel/|clinic-modules/clinic-modules\.(service|controller)\.(js|js\.map|d\.ts)$|live-updates/live-updates\.module\.(js|js\.map|d\.ts)$))'){continue};$count++;if(-not $new.PSObject.Properties[$p.Name] -or $new.PSObject.Properties[$p.Name].Value -ne $p.Value){throw "Unrelated runtime changed: $($p.Name)"}}
foreach($p in $new.PSObject.Properties){if(-not $old.PSObject.Properties[$p.Name] -and $p.Name -notmatch '/dist/modules/pet-hotel/'){throw "Unexpected runtime file: $($p.Name)"}}
$m.protectedApiFiles=$count;[IO.File]::WriteAllText((Join-Path $PackagePath 'release.json'),($m|ConvertTo-Json -Depth 12),(New-Object Text.UTF8Encoding($false)))
Write-Output "BUILD_OK: $count unrelated API files byte-identical, including billing and live Avito; both candidates amd64."
